#!/usr/bin/env python3
"""Complete the missing EvoETD parameter-sensitivity experiments on a Kaggle GPU.

This is a self-contained launcher: the two source runners are embedded below.
It adds only four one-factor-at-a-time cases:
  PDE1 chart extension: eta=2.0 (baseline eta=3.0)
  PDE2:                 eta=1.4 (baseline eta=2.2)
  PDE3:                 eta=2.0 (baseline eta=3.0)
  PDE3:                 mu=0.95 (baseline mu=0.70)

Default models are the two models used by the existing sensitivity group:
Connection-ETD-Fibre and Scalar-Laplacian-ETD-Fibre.

Kaggle use:
  1. Enable a GPU accelerator (Tesla T4).
  2. Upload this single .py file to /kaggle/working or a Kaggle notebook.
  3. Run: !python /kaggle/working/evoetd_parameter_sensitivity_completion.py

You can pass runner options after the launcher options, e.g.
  !python evoetd_parameter_sensitivity_completion.py --seeds 17 29 41 53 65 71 83 97 109 127
       --epochs 45 --device cuda:0

IMPORTANT: Change DEFAULT_SEEDS below (or pass --seeds) to the exact training
seed list used for the already-reported sensitivity experiments. The embedded
runners' unmodified defaults are 7 seeds for the PDE1 chart runner and 5 for
PDE2/PDE3; this launcher defaults to a shared 10-seed list for convenience.
The new results should use the same seed IDs as the existing table wherever
possible. All reference-trajectory split seeds and the training/evaluation
protocol are inherited unchanged from the embedded source runners.
"""
from __future__ import annotations

import argparse
import base64
import dataclasses
import importlib.util
import json
import os
from pathlib import Path
import sys
import tempfile
import textwrap
import zlib

import pandas as pd

# EDIT OR OVERRIDE THIS LIST TO MATCH THE SEEDS USED IN THE EXISTING PAPER TABLE.
DEFAULT_SEEDS = [17, 29, 41, 53, 65, 71, 83, 97, 109, 127]
DEFAULT_OUT = Path('/kaggle/working/evoetd_parameter_sensitivity_completion')
EXPECTED_MODELS = ('Connection-ETD-Fibre', 'Scalar-Laplacian-ETD-Fibre')

# Compressed, unchanged experiment runners shipped inside this file.
PDE1_RUNNER_ZLIB_B64 = ""
PDE23_RUNNER_ZLIB_B64 = ""


def _materialize_runner_sources() -> Path:
    """Write embedded original source runners to a temporary import directory."""
    root = Path(tempfile.gettempdir()) / 'evoetd_sensitivity_runner_sources_v1'
    root.mkdir(parents=True, exist_ok=True)
    files = {
        'run_bundle_pde_validation_v6.py': PDE1_RUNNER_ZLIB_B64,
        'run_connection_operator_extensions_v5.py': PDE23_RUNNER_ZLIB_B64,
    }
    for filename, payload in files.items():
        out = root / filename
        raw = zlib.decompress(base64.b64decode(payload.encode('ascii')))
        # Re-write if absent or different, so a stale file cannot silently be used.
        if not out.exists() or out.read_bytes() != raw:
            out.write_bytes(raw)
    return root


def _load_module(module_name: str, source_path: Path):
    spec = importlib.util.spec_from_file_location(module_name, source_path)
    if spec is None or spec.loader is None:
        raise RuntimeError(f'Could not load embedded runner: {source_path}')
    module = importlib.util.module_from_spec(spec)
    sys.modules[module_name] = module
    spec.loader.exec_module(module)
    return module


def _patch_pde1_runner(module) -> list[str]:
    original_catalogue = module.case_catalogue

    def extended_catalogue():
        cases = original_catalogue()
        base = cases['pde1_chart_base']
        cases['pde1_eta_low'] = dataclasses.replace(
            base,
            name='pde1_eta_low',
            eta=2.0,
            model_group='sensitivity',
            description='PDE1 saturation sensitivity: eta=2.0 (baseline eta=3.0).',
        )
        return cases

    module.case_catalogue = extended_catalogue
    module.DEFAULT_CASES = list(extended_catalogue().keys())
    module.RUNNER_VERSION = str(module.RUNNER_VERSION) + '-parameter-sensitivity-completion-v1'
    return ['pde1_eta_low']


def _patch_pde23_runner(module) -> list[str]:
    original_catalogue = module.case_catalogue

    def extended_catalogue():
        cases = original_catalogue()
        pde2 = cases['pde2_base']
        pde3 = cases['pde3_base']
        cases['pde2_eta_low'] = dataclasses.replace(
            pde2,
            name='pde2_eta_low',
            eta=1.4,
            model_group='sensitivity',
            description='PDE2 saturation sensitivity: eta=1.4 (baseline eta=2.2).',
        )
        cases['pde3_eta_low'] = dataclasses.replace(
            pde3,
            name='pde3_eta_low',
            eta=2.0,
            model_group='sensitivity',
            description='PDE3 bulk-saturation sensitivity: eta=2.0 (baseline eta=3.0).',
        )
        cases['pde3_mu_high'] = dataclasses.replace(
            pde3,
            name='pde3_mu_high',
            mu=0.95,
            model_group='sensitivity',
            description='PDE3 ordering-growth sensitivity: mu=0.95 (baseline mu=0.70).',
        )
        return cases

    module.case_catalogue = extended_catalogue
    module.DEFAULT_CASES = list(extended_catalogue().keys())
    module.RUNNER_VERSION = str(module.RUNNER_VERSION) + '-parameter-sensitivity-completion-v1'
    return ['pde2_eta_low', 'pde3_eta_low', 'pde3_mu_high']


def _run_module(module, argv: list[str]) -> None:
    old_argv = sys.argv
    try:
        sys.argv = [str(getattr(module, '__file__', 'embedded_runner.py'))] + argv
        module.main()
    finally:
        sys.argv = old_argv


def _print_configuration(pde1_seeds: list[int], pde23_seeds: list[int], output: Path, device: str, runner_args: list[str]) -> None:
    print('\n=== EvoETD missing parameter-sensitivity cases ===', flush=True)
    print(f'Output directory: {output}', flush=True)
    print(f'Device: {device}', flush=True)
    print(f'PDE1 training seeds ({len(pde1_seeds)}): {pde1_seeds}', flush=True)
    print(f'PDE2/PDE3 training seeds ({len(pde23_seeds)}): {pde23_seeds}', flush=True)
    print('Models: Connection-ETD-Fibre; Scalar-Laplacian-ETD-Fibre', flush=True)
    print('Cases:', flush=True)
    print('  PDE1 chart: baseline (nu, mu, eta)=(0.02, 0.70, 3.0); eta=2.0', flush=True)
    print('  PDE2:       baseline (nu, mu, eta)=(0.035, 0.55, 2.2); eta=1.4', flush=True)
    print('  PDE3:       baseline (nu, mu, eta)=(0.02, 0.70, 3.0); eta=2.0 and mu=0.95', flush=True)
    print('All other PDE coefficients, geometry, data split protocol, optimizer,', flush=True)
    print('model architecture, and evaluation settings are inherited from the', flush=True)
    print('corresponding original runner. Each case is trained independently.', flush=True)
    if runner_args:
        print(f'Additional original-runner arguments: {runner_args}', flush=True)


def _collect_horizon_summary(output: Path, expected_seed_counts: dict[str, int]) -> None:
    """Collect horizon-75 means/stds and print a compact fill-in table."""
    case_roots = {
        'pde1_eta_low': output / 'pde1_chart' / 'pde1_eta_low',
        'pde2_eta_low': output / 'pde23' / 'pde2_eta_low',
        'pde3_eta_low': output / 'pde23' / 'pde3_eta_low',
        'pde3_mu_high': output / 'pde23' / 'pde3_mu_high',
    }
    rows = []
    for case_name, case_dir in case_roots.items():
        summary_path = case_dir / 'summary.csv'
        if not summary_path.exists():
            print(f'[SUMMARY-MISSING] {case_name}: {summary_path} not found', flush=True)
            continue
        try:
            df = pd.read_csv(summary_path)
            if 'horizon' not in df or 'model' not in df:
                raise ValueError('summary.csv does not contain expected columns')
            h75 = df[df['horizon'].astype(int) == 75]
            for model in EXPECTED_MODELS:
                part = h75[h75['model'] == model]
                if part.empty:
                    print(f'[SUMMARY-MISSING] {case_name} / {model}: horizon 75 row absent', flush=True)
                    continue
                for _, row in part.iterrows():
                    n = int(row['n_seeds'])
                    item = {
                        'case': case_name,
                        'model': model,
                        'horizon': 75,
                        'mean_rel_l2': float(row['mean']),
                        'seed_std': float(row['seed_std']),
                        'n_seeds': n,
                    }
                    rows.append(item)
                    print(
                        f"[H=75] {case_name:14s} | {model:31s} | "
                        f"{item['mean_rel_l2']:.6f} +/- {item['seed_std']:.6f} "
                        f"(n={n})",
                        flush=True,
                    )
                    expected = expected_seed_counts[case_name]
                    if n != expected:
                        print(
                            f'  WARNING: expected {expected} seeds but summary reports {n}; '
                            'check failures.csv and run_manifest.csv.',
                            flush=True,
                        )
        except Exception as exc:
            print(f'[SUMMARY-ERROR] {case_name}: {exc!r}', flush=True)

    if rows:
        out_csv = output / 'missing_parameter_sensitivity_horizon75.csv'
        pd.DataFrame(rows).to_csv(out_csv, index=False)
        tex_lines = [
            r'\begin{tabular}{llrr}',
            r'\hline',
            r'Case & Model & Relative $L^2$ (H=75) & $n$ \\',
            r'\hline',
        ]
        for r in rows:
            case = r['case'].replace('_', r'\_')
            model = r['model'].replace('-', r'\text{-}')
            val = f"{r['mean_rel_l2']:.6f} $\\pm$ {r['seed_std']:.6f}"
            tex_lines.append(f"{case} & {model} & {val} & {r['n_seeds']} \\\\")
        tex_lines.extend([r'\hline', r'\end{tabular}'])
        out_tex = output / 'missing_parameter_sensitivity_horizon75.tex'
        out_tex.write_text('\n'.join(tex_lines) + '\n', encoding='utf-8')
        print(f'\nSaved: {out_csv}', flush=True)
        print(f'Saved: {out_tex}', flush=True)
    else:
        print('[SUMMARY] No completed horizon-75 results found yet.', flush=True)


def main() -> None:
    parser = argparse.ArgumentParser(
        description='Run the four missing EvoETD PDE parameter-sensitivity experiments.',
        formatter_class=argparse.ArgumentDefaultsHelpFormatter,
    )
    parser.add_argument('--out', type=Path, default=DEFAULT_OUT,
                        help='Root output folder (created under /kaggle/working by default).')
    parser.add_argument('--device', default='cuda:0',
                        help='Use cuda:0 for the Kaggle T4; may be changed to auto or cpu for debugging.')
    parser.add_argument('--cpu-threads', type=int, default=4)
    parser.add_argument('--seeds', type=int, nargs='+', default=DEFAULT_SEEDS,
                        help='Shared training seed IDs for all PDEs (unless a PDE-specific list is supplied).')
    parser.add_argument('--pde1-seeds', type=int, nargs='+', default=None,
                        help='Optional PDE1-only seed list; overrides --seeds for PDE1.')
    parser.add_argument('--pde23-seeds', type=int, nargs='+', default=None,
                        help='Optional shared PDE2/PDE3 seed list; overrides --seeds for PDE2/PDE3.')
    parser.add_argument('--print-only', action='store_true',
                        help='Print the case plan without launching training.')
    args, runner_args = parser.parse_known_args()
    if runner_args and runner_args[0] == '--':
        runner_args = runner_args[1:]
    pde1_seeds = args.pde1_seeds if args.pde1_seeds is not None else args.seeds
    pde23_seeds = args.pde23_seeds if args.pde23_seeds is not None else args.seeds
    for label, seeds in [('PDE1', pde1_seeds), ('PDE2/PDE3', pde23_seeds)]:
        if not seeds or len(set(seeds)) != len(seeds):
            raise ValueError(f'{label} training seeds must be non-empty and unique.')
    if args.cpu_threads < 1:
        raise ValueError('--cpu-threads must be >= 1.')

    _print_configuration(pde1_seeds, pde23_seeds, args.out, args.device, runner_args)
    if args.print_only:
        return

    source_root = _materialize_runner_sources()
    pde1_module = _load_module(
        'evoetd_embedded_pde1_runner', source_root / 'run_bundle_pde_validation_v6.py'
    )
    pde23_module = _load_module(
        'evoetd_embedded_pde23_runner', source_root / 'run_connection_operator_extensions_v5.py'
    )
    pde1_cases = _patch_pde1_runner(pde1_module)
    pde23_cases = _patch_pde23_runner(pde23_module)

    # Enforce the requested GPU rather than silently falling back to CPU.
    import torch
    if args.device.startswith('cuda'):
        if not torch.cuda.is_available():
            raise RuntimeError('CUDA is unavailable. In Kaggle, enable a GPU accelerator before running.')
        device_index = 0
        if ':' in args.device:
            device_index = int(args.device.split(':', 1)[1])
        if device_index >= torch.cuda.device_count():
            raise RuntimeError(
                f'Requested {args.device}, but only {torch.cuda.device_count()} CUDA device(s) are visible.'
            )
        gpu_name = torch.cuda.get_device_name(device_index)
        print(f'\n[GPU] {args.device}: {gpu_name}', flush=True)
        if 'T4' not in gpu_name.upper():
            print('[GPU-WARNING] The visible GPU is not named Tesla T4; proceeding on the selected CUDA device.', flush=True)
    elif args.device != 'auto' and args.device != 'cpu':
        raise ValueError("--device must be 'cuda:0', another visible CUDA device, 'auto', or 'cpu'.")

    args.out.mkdir(parents=True, exist_ok=True)
    pde1_out = args.out / 'pde1_chart'
    pde23_out = args.out / 'pde23'

    common_pde1 = ['--seeds', *[str(x) for x in pde1_seeds], '--device', args.device,
                   '--cpu-threads', str(args.cpu_threads)] + runner_args
    common_pde23 = ['--seeds', *[str(x) for x in pde23_seeds], '--device', args.device,
                    '--cpu-threads', str(args.cpu_threads)] + runner_args

    print('\n========== RUN 1/2: PDE1 chart-extension low-eta case ==========', flush=True)
    _run_module(pde1_module, ['--out', str(pde1_out), '--cases', *pde1_cases] + common_pde1)

    print('\n========== RUN 2/2: PDE2/PDE3 missing sensitivity cases ==========', flush=True)
    _run_module(pde23_module, ['--out', str(pde23_out), '--cases', *pde23_cases] + common_pde23)

    expected_counts = {
        'pde1_eta_low': len(pde1_seeds),
        'pde2_eta_low': len(pde23_seeds),
        'pde3_eta_low': len(pde23_seeds),
        'pde3_mu_high': len(pde23_seeds),
    }
    _collect_horizon_summary(args.out, expected_seed_counts=expected_counts)
    print('\n[COMPLETE] Four missing parameter-sensitivity cases have finished.', flush=True)
    print(f'[COMPLETE] Results are in: {args.out.resolve()}', flush=True)


if __name__ == '__main__':
    main()
